def total(precos, quantidades):
    if len(precos) != len(quantidades):
        raise ValueError("Listas de preços e quantidades devem ter o mesmo tamanho.")

    soma = 0.0
    for preco, quantidade in zip(precos, quantidades):
        if quantidade < 0:
            raise ValueError("Quantidade não pode ser negativa.")
        soma += preco * quantidade
    return soma

if __name__ == "__main__":
    # Testes solicitados
    assert total([10, 2.5], [2, 3]) == 27.5
    assert total([], []) == 0

